//--------------------------------------------------------------------------
// Description:
//  - Multi-port UDP/IPv4 GMII ethernet interface driver with MDIO
//
//==========================================================================

module bfm_ethernet
#(parameter                            START_NODE     = 1,
  parameter                            NUM_PORTS      = 4,
  parameter                            MDIO_BUFF_ADDR = 32'h50000000,
  parameter                            RGMII          = 1)
(
  input                                clk,
  input                                clkx2,
  input                                arst_n,

  // GMII interface
  gmii_if.SLV                          gmii [0:NUM_PORTS-1],

  // MDIO interface
  input                                mdioclk,
  inout       [NUM_PORTS-1:0]          mdio,

`ifdef VERILATOR
  output      [NUM_PORTS-1:0]          mdio_en,
  output      [NUM_PORTS-1:0]          mdio_out,
`endif

  // Simulation halt request
  output                               halt_req
);

wire [7:0] udp_gmii_rxd  [NUM_PORTS-1:0];
wire       udp_gmii_rxdv [NUM_PORTS-1:0];
wire       udp_gmii_rxer [NUM_PORTS-1:0];
wire [7:0] udp_gmii_txd  [NUM_PORTS-1:0];
wire       udp_gmii_txen [NUM_PORTS-1:0];
wire       udp_gmii_txer [NUM_PORTS-1:0];

wire [NUM_PORTS-1:0] halt;

//--------------------------------------------------------------------------
// Combinatorial logic
//--------------------------------------------------------------------------

assign halt_req                        = |halt;

//--------------------------------------------------------------------------
// BFM instantiations
//--------------------------------------------------------------------------

genvar UDP;
generate

  for (UDP = 0; UDP < NUM_PORTS; UDP++)
  begin

    if (RGMII)
    begin:gen_rgmii
      // When RGMII, instantiate convertor and use gmii_if.tx[3:0], gmii_if.rdx[3:0], gmii_if.txen and
      // gmii_if.rxdv for the RGMI signalling.
      gmii_rgmii_conv conv
      (
        .clk                           (clk),
        .clkx2                         (clkx2),

        // GMII to RGMII
        .gmiitxd                       (udp_gmii_txd[UDP]),
        .gmiitxen                      (udp_gmii_txen[UDP]),
        .gmiitxer                      (udp_gmii_txer[UDP]),

        .rgmiitxd                      (gmii[UDP].rxd[3:0]),
        .rgmiitxctl                    (gmii[UDP].rxdv),

        // RGMII to GMII
        .rgmiirxd                      (gmii[UDP].txd[3:0]),
        .rgmiirxctl                    (gmii[UDP].txen),

        .gmiirxd                       (udp_gmii_rxd[UDP]),
        .gmiirxdv                      (udp_gmii_rxdv[UDP]),
        .gmiirxer                      (udp_gmii_rxer[UDP])
      );

      // Tie off unused outputs
      assign gmii[UDP].rxd[7:4]        = '0;
      assign gmii[UDP].rxer            = '0;
    end
    else
    begin:gen_gmii
       // When in GMII mode, wire interface straight through to udpIpPg
       assign gmii[UDP].rxd            = udp_gmii_txd[UDP];
       assign gmii[UDP].rxdv           = udp_gmii_txen[UDP];
       assign gmii[UDP].rxer           = udp_gmii_txer[UDP];

       assign udp_gmii_rxd[UDP]        = gmii[UDP].txd;
       assign udp_gmii_rxdv[UDP]       = gmii[UDP].txen;
       assign udp_gmii_rxer[UDP]       = gmii[UDP].txer;
    end

    // UDP/IPv4 ethernet BFM
    udp_ip_pg #(
      .NODE(START_NODE+UDP)
    ) udpIpPg
    (
      .clk                             (clk),

      .txd                             (udp_gmii_txd[UDP]),
      .txen                            (udp_gmii_txen[UDP]),
      .txer                            (udp_gmii_txer[UDP]),

      .rxd                             (udp_gmii_rxd[UDP]),
      .rxdv                            (udp_gmii_rxdv[UDP]),
      .rxer                            (udp_gmii_rxer[UDP]),

      .halt                            (halt[UDP])
    );

    // PHY MDIO slave BFM
    bfm_phy_mdio #(
      .MDIO_BUFF_ADDR                  (MDIO_BUFF_ADDR + UDP*256),
      .NODE                            (START_NODE+UDP)
    ) phymdio
    (
      .clk                             (mdioclk),
      .arst_n,

`ifdef VERILATOR
      .mdio_en                         (mdio_en[UDP]),
      .mdio_out                        (mdio_out[UDP]),
`endif

      .mdio                            (mdio[UDP])
    );

  end

endgenerate

endmodule

// SPDX-License-Identifier: GPL-3.0-or-later

/*
 * Verilog side UDP/IPv4 packet generator, built around VProc
 *
 * Copyright (c) 2025 Simon Southwell.
 *
 * This file is part of udp_ip_pg.
 *
 * This code is free software: you can redistribute it and/or modify
 * it under the terms of the GNU General Public License as published by
 * the Free Software Foundation, either version 3 of the License, or
 * (at your option) any later version.
 *
 * The code is distributed in the hope that it will be useful,
 * but WITHOUT ANY WARRANTY; without even the implied warranty of
 * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the
 * GNU General Public License for more details.
 *
 * You should have received a copy of the GNU General Public License
 * along with this code. If not, see <http://www.gnu.org/licenses/>.
 *
 */

// --------------------------------------------
// Timescale
// --------------------------------------------

`timescale 1ps/1ps

// --------------------------------------------
// Definitions
// --------------------------------------------

`define TXD_ADDR                      32'h0
`define TXC_ADDR                      32'h1
`define TICKS_ADDR                    32'h2
`define HLT_ADDR                      32'h3

// ============================================
//  MODULE
// ============================================

module udp_ip_pg
#(parameter                            NODE    = 0)
(
  input                                clk,

  // GMII interface
  output reg  [7:0]                    txd,
  output reg                           txen,
  output reg                           txer,

  input       [7:0]                    rxd,
  input                                rxdv,
  input                                rxer,

  output reg                           halt
);

// --------------------------------------------
// Signal definitions
// --------------------------------------------

integer     count;

wire [31:0] nodenum = NODE;
wire [31:0] Addr;
wire        WE;
wire        RD;
wire [31:0] DataOut;
reg  [31:0] DataIn;
wire        Update;
reg         UpdateResponse;

// --------------------------------------------
// Continuous assignments
// --------------------------------------------

// Ensure there is no race on the update ordering on
// the rising edge of the clock between updating the
// inputs and the synchronous process below being called.

`ifndef VERILATOR

wire  [7:0] rxd_int;
wire  [1:0] rxc_int;

assign #1   rxd_int                    = rxd;
assign #1   rxc_int                    = {rxer, rxdv};

`else

reg   [7:0] rxd_int;
reg   [1:0] rxc_int;

always @(negedge clk)
begin
  rxd_int                              <= rxd;
  rxc_int                              <= {rxer, rxdv};
end

`endif

// --------------------------------------------
// Initialisation
// --------------------------------------------

initial
begin
  UpdateResponse                       = 1'b1;
  txd                                  = 8'h00;
  txen                                 = 1'b0;

  count                                = 0;
  halt                                 = 1'b0;
end

// --------------------------------------------
// Process to generate a tick count
// --------------------------------------------

always @(posedge clk)
begin
  count                                <= count + 1;
end

// --------------------------------------------
// Asynchronous process to access the ports and
// internal state.
// --------------------------------------------

always @(Update)
begin

  DataIn           = 32'h0;

  if (WE == 1'b1 || RD == 1'b1)
  begin
    case (Addr)

    // Update the TXD low word, if a write, and read the low RXD inputs
    `TXD_ADDR: begin
      DataIn                           = {24'h0, rxd_int};
      if (WE == 1'b1)
      begin
        txd                            = DataOut[7:0];
      end
    end
    // Update the TXC bits, if a write, and read the RXC inputs
    `TXC_ADDR: begin
      DataIn                           = {30'h0, rxc_int};
      if (WE == 1'b1)
      begin
        txen                           = DataOut[0];
        txer                           = DataOut[1];
      end
    end

    // This address must be accessed as a delta update since
    // it does not read the RX inputs
    `TICKS_ADDR: begin
      DataIn                           = count;
    end

    // It is recommended that this address is accessed as a delta
    // update in case a packet is being received and the sim does
    // not halt immediately. Assume it is a 'request' to halt to the
    // external logic.
    `HLT_ADDR: begin
      if (WE == 1'b1)
      begin
        halt                           = DataOut[0];
      end
    end

    // Only the above addresses are valid.
    default: begin
       $display("***ERROR: udp_ip_pg---access to invalid address from VProc");
       $finish;
    end
    endcase
  end

  // Acknowledge the access by inverting the response input to VProc
  UpdateResponse                       = ~UpdateResponse;
end

  // --------------------------------------------
  // Virtual Processor to run packet generation
  // software.
  // --------------------------------------------

  VProc vp (
   .Clk                                (clk),
   .Addr                               (Addr),

`ifdef VPROC_BYTE_ENABLE
   .BE                                 (),
`endif

   .WE                                 (WE),
   .RD                                 (RD),
   .DataOut                            (DataOut),
   .DataIn                             (DataIn),
   .WRAck                              (WE),
   .RDAck                              (RD),

`ifdef VPROC_BURST_IF
    // Burst count
    .Burst                             (),
    .BurstFirst                        (),
    .BurstLast                         (),
`endif

   .Interrupt                          (3'b000),
   .Update                             (Update),
   .UpdateResponse                     (UpdateResponse),
   .Node                               (nodenum[3:0])
  );

endmodule

