18	// but WITHOUT ANY WARRANTY; without even the implied warranty of
19	// MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the
20	// GNU General Public License for more details.
21	//
22	// You should have received a copy of the GNU General Public License
23	// along with this code. If not, see <http://www.gnu.org/licenses/>.
24	//
25	//=============================================================
26	
27	#ifndef _UDP_VPROC_H_
28	#define _UDP_VPROC_H_
29	
30	#include <stdio.h>
31	#include <stdint.h>
32	
33	extern "C" {
34	#include "VUser.h"
35	}
36	
37	class udpVProc
38	{
39	
40	protected :
41	
42	    // Virtual method, provided by derived class, where received data is sent
43	    virtual uint32_t processFrame (uint32_t* rx_buf, uint32_t rx_len) = 0;
44	
45	    // The VProc node for the udpClient HDL model
46	    int              node;
47	
48	public:
49	
50	    // --------------------------------------------
51	    // Static constants
52	    // --------------------------------------------
53	
54	    // udpClient VProc address offsets
55	    static const uint32_t TXD_ADDR             = 0;
56	    static const uint32_t TXC_ADDR             = 1;
57	    static const uint32_t TICKS_ADDR           = 2;
58	    static const uint32_t HALT_ADDR            = 3;
59	
60	    // Ethernet tags and frame delimeters
61	    static const uint32_t IDLE                 = 0x07;
62	    static const uint32_t SOF                  = 0xfb;
63	    static const uint32_t EoF                  = 0xfd;
64	    static const uint32_t PREAMBLE             = 0x55;
65	    static const uint32_t SFD                  = 0xd5;
66	
67	    static const uint32_t RX_VALID_MASK        = 0x01;
68	    static const uint32_t RX_ERROR_MASK        = 0x02;
69	    static const uint32_t TX_ERROR_MASK        = 0x100;
70	    static const uint32_t TX_CTRL_IDLE         = 0x00;
71	    static const uint32_t TX_CTRL_VALID        = 0x01;
72	    static const uint32_t TX_CTRL_ERROR        = 0x03;
73	
74	    // Ethernet parameters and header dimensions
75	    static const uint32_t ETH_MTU              = 1500;
76	    static const uint32_t ETH_PREAMBLE         = 8;  // BYTES
77	    static const uint32_t ETH_802_1Q_LEN       = 4;  // BYTES
78	    static const uint32_t ETH_CRC_LEN          = 4;  // BYTES
79	    static const uint32_t ETH_HDR_LEN          = 14; // BYTES
80	
81	    // --------------------------------------------
82	    // Constructor
83	    // --------------------------------------------
84	
85	    udpVProc(int nodeIn) : node(nodeIn)
86	    {
87	        currTickCount                  = 0xffffffff;
88	        receiving_frame                = false;
89	        rx_idx                         = 0;
90	    };
91	
92	    // --------------------------------------------------
93	    // Method to idle for specified number of cycles
94	    // --------------------------------------------------
95	
96	    uint32_t UdpVpSendIdle(uint32_t ticks)
97	    {
98	        uint32_t error = 0;
99	        uint32_t currTicks;
100	
101	        VWrite(TXD_ADDR, IDLE,         true, node);
102	        VWrite(TXC_ADDR, TX_CTRL_IDLE, true, node);
103	
104	        // Get start time
105	        for (int idx = 0; idx < ticks; idx++)
106	        {
107	            VRead(TICKS_ADDR, &currTicks, true, node);
108	
109	            UdpVpExtractRx();
110	        }
111	
112	        return error;
113	    }
114	
115	    // --------------------------------------------------
116	    // Method to send a pre-prepared (raw) ethernet frame
117	    // --------------------------------------------------
118	    uint32_t UdpVpSendRawEthFrame(uint32_t* frame, uint32_t len)
119	    {
120	        uint32_t error = 0;
121	
122	        // Construct 64 bit TXD words and associated TXC byte from frame data,
123	        // flushed to 64 bit boundary
124	        for (int idx = 0; idx < len; idx++)
125	        {
126	            // Send out byte
127	            VWrite(TXD_ADDR, frame[idx] & 0xff, true, node);
128	
129	            // TX control bit
130	#ifdef GENERATE_SOF_EOF
131	            uint32_t txc = (frame[idx] & TX_ERROR_MASK) ? TX_CTRL_ERROR : (idx == 0 || idx == (len-1)) ? 0 : TX_CTRL_VALID;
132	#else
133	            uint32_t txc = (frame[idx] & TX_ERROR_MASK) ? TX_CTRL_ERROR : TX_CTRL_VALID;
134	#endif
135	            VWrite(TXC_ADDR, txc, true, node);
136	
137	            // Extract RX data and advance tick
138	            UdpVpExtractRx();
139	        }
140	
141	        UdpVpSendIdle(1);
142	
143	        return error;
144	    }
145	
146	    // --------------------------------------------------
147	    // Method to set the halt output signal
148	    // --------------------------------------------------
149	    void UdpVpSetHalt(uint32_t val) {VWrite(HALT_ADDR, val & 0x1, false, node);}
150	
151	private:
152	
153	    // --------------------------------------------------
154	    // Method to extract received data from VProc input
155	    // interface.
156	    // --------------------------------------------------
157	    void UdpVpExtractRx ()
158	    {
159	        uint32_t rxd, rxc;
160	        uint32_t clk_count;
161	        bool     error_detected;
162	
163	        // If the current tick count is uninitialised, fetch clock tick count from the HDL,
164	        // else increment for each read cycle.
165	        if (currTickCount == 0xffffffff)
166	        {
167	            VRead(TICKS_ADDR, &currTickCount, true, node);
168	        }
169	        else
170	        {
171	            currTickCount++;
172	        }
173	
174	        // Read the input pins: the 8 bits of data and 2 of control
175	        VRead(TXD_ADDR, &rxd,     true,  node);
176	        VRead(TXC_ADDR, &rxc,     false, node);
177	
178	        // Extract the data byte, with bit 8 as the control bit
179	        uint32_t rxbyte = rxd & 0xff;
180	
181	        // If not receiving a frame already, and a new frame detected,
182	        // flag receiving and reset the RX buffer index
183	        if (!receiving_frame && (rxc & RX_VALID_MASK))
184	        {
185	            receiving_frame = true;
186	            error_detected  = false;
187	            rx_idx          = 0;
188	        }
189	
190	        // If receving a frame...
191	        if (receiving_frame)
192	        {
193	            // If an end-of-frame detected, clear the receiving frame state, and call the
194	            // method to process the data,
195	            if (!(rxc & RX_VALID_MASK))
196	            {
197	                receiving_frame = false;
198	
199	                // Calculate length of preamble and SFD (could be variable)
200	                int pidx = 0;
201	                while (rx_buf[pidx] == PREAMBLE || rx_buf[pidx] == SFD)
202	                {
203	                    pidx++;
204	                }
205	
206	                // Process input if no errors were seen
207	                if (!error_detected)
208	                {
209	                    // Process input, subtracting the Premable and SFD
210	                    processFrame(&rx_buf[pidx], rx_idx-pidx);
211	                }
212	            }
213	            // Whilst receiving a frame, place it in the receive buffer
214	            else
215	            {
216	                error_detected |= rxc & RX_ERROR_MASK;
217	                if (rx_idx == (ETH_MTU + ETH_HDR_LEN + ETH_PREAMBLE + ETH_CRC_LEN + ETH_802_1Q_LEN))
218	                {
219	                    printf("WARNING: received packet of maximum size without completing frame. Terminating packet\n");
220	                    receiving_frame = false;
221	                    error_detected  = true;
222	                }
223	                else
224	                {
225	                    rx_buf[rx_idx++] = rxbyte;
226	                }
227	            }
228	        }
229	    }
230	
231	    // -------------------------------------------------
232	    // Private member variables
233	    // -------------------------------------------------
234	
235	    // Clock tick count (nominally at 6.4ns) to give timing
236	    uint32_t       currTickCount;
237	
238	    // State flag to indicate actively receiving data
239	    bool           receiving_frame;
240	
241	    // Receive buffer and index. Buffer size is the maximum for largest payload, plus headers
242	    uint32_t       rx_buf[ETH_MTU + ETH_HDR_LEN + ETH_PREAMBLE + ETH_CRC_LEN + ETH_802_1Q_LEN];
243	    uint32_t       rx_idx;
244	
245	};
246	
247	#endif
