//  GMII interface
//==========================================================================

interface gmii_if (
   input  logic arst_n, // asynchronous, active-low reset
   input  logic clk     // bus clock
);

   logic [7:0]     txd;
   logic           txen;
   logic           txer;

   logic [7:0]     rxd;
   logic           rxdv;
   logic           rxer;

  //----------------------------------------
  // master side
  //----------------------------------------
   modport MST (
     output txd,
            txen,
            txer,

     input  arst_n, clk,
            rxd,
            rxdv,
            rxer
   );

  //----------------------------------------
  // Slave side
  //----------------------------------------
   modport SLV (
     input  arst_n, clk,
            txd,
            txen,
            txer,

     output rxd,
            rxdv,
            rxer
   );

endinterface: gmii_if

